solution:
def floor_sqrt(x: int) -> int:
    lo, hi = 0, x + 1                # the first r with r * r > x is in [0, x + 1]
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * mid > x:
            hi = mid
        else:
            lo = mid + 1
    return lo - 1                    # the last r with r * r <= x

